// Parse a document in a subset of JSON and return it in canonical form, or
// None if the document is invalid.
// The document is exactly one value, optionally surrounded by whitespace.
// Values: objects {"key": value, ...}, arrays [value, ...], strings, integers,
// true, false and null. Whitespace (space, tab, newline, carriage return) may
// appear before and after any value, comma, colon or bracket.
// - Strings are enclosed in double quotes. A raw newline inside a string is
//   invalid. The only escapes are \" \\ \/ \n and \t; any other escape
//   (\u included) is invalid.
// - Integers: an optional '-', then one or more ASCII digits with no leading
//   zero unless the digits are exactly "0" ("-0" is valid, "01" is not).
//   Fractions and exponents are invalid.
// - Object keys are strings. Two keys that are equal after decoding escapes
//   make the document invalid. Trailing commas are invalid.
// - Anything after the value other than whitespace is invalid; so is an empty
//   or all-whitespace document.
// Canonical form: no whitespace at all; integers in plain decimal ("-0" becomes
// "0"); object members sorted by decoded key, in ascending character-code
// order; strings re-encoded with exactly these escapes: '"' as \", '\' as
// \\, newline as \n and tab as \t ('/' is written plainly).
// Examples (the strings below are Overlang literals):
//   canonical_json(" { \"b\" : [1, -0, \"x\\/y\"], \"a\": {} } ") == Some("{\"a\":{},\"b\":[1,0,\"x/y\"]}")
//   canonical_json("[1, 2,]") == None
fn canonical_json(text: Str) -> Option[Str] {
  let cs = chars(text);
  let (v, p) = json_value(cs, 0)?;
  if skip_ws(cs, p) == len(cs) { Some(v) } else { None }
}

fn at(cs: List[Str], p: Int) -> Str { unwrap_or(get(cs, p), "") }

fn skip_ws(cs: List[Str], p0: Int) -> Int {
  let mut p = p0;
  while at(cs, p) == " " || at(cs, p) == "\t" || at(cs, p) == "\n" || at(cs, p) == "\r" {
    p = p + 1;
  }
  p
}

fn expect_char(cs: List[Str], p0: Int, c: Str) -> Option[Int] {
  let p = skip_ws(cs, p0);
  if at(cs, p) == c { Some(p + 1) } else { None }
}

fn json_string(cs: List[Str], p0: Int) -> Option[(Str, Int)] {
  let mut p = expect_char(cs, p0, "\"")?;
  let mut out: List[Str] = [];
  while p < len(cs) && cs[p] != "\"" {
    let c = cs[p];
    if c == "\n" {
      return None;
    }
    if c == "\\" {
      let e = at(cs, p + 1);
      let d = match e {
        "n" => "\n",
        "t" => "\t",
        "\"" | "\\" | "/" => e,
        _ => { return None; },
      };
      out = push(out, d);
      p = p + 2;
    } else {
      out = push(out, c);
      p = p + 1;
    }
  }
  let q = expect_char(cs, p, "\"")?;
  Some((join(out, ""), q))
}

fn json_encode(s: Str) -> Str {
  let a = replace(replace(s, "\\", "\\\\"), "\"", "\\\"");
  "\"" ++ replace(replace(a, "\n", "\\n"), "\t", "\\t") ++ "\""
}

fn word_at(cs: List[Str], p: Int, w: Str) -> Bool {
  p + str_len(w) <= len(cs) && join(slice(cs, p, p + str_len(w)), "") == w
}

fn json_value(cs: List[Str], p0: Int) -> Option[(Str, Int)] {
  let p = skip_ws(cs, p0);
  let c = at(cs, p);
  if c == "{" || c == "[" {
    return json_container(cs, p + 1, c == "{");
  }
  if c == "\"" {
    let (s, q) = json_string(cs, p)?;
    return Some((json_encode(s), q));
  }
  for w in ["true", "false", "null"] {
    if word_at(cs, p, w) {
      return Some((w, p + str_len(w)));
    }
  }
  let digits = if c == "-" { p + 1 } else { p };
  let mut q = digits;
  while is_digit(at(cs, q)) {
    q = q + 1;
  }
  if q == digits || (cs[digits] == "0" && q - digits > 1) {
    return None;
  }
  let n = parse_int(join(slice(cs, p, q), ""))?;
  Some((show(n), q))
}

fn json_container(cs: List[Str], p0: Int, is_obj: Bool) -> Option[(Str, Int)] {
  let close = if is_obj { "}" } else { "]" };
  let mut items: List[(Str, Str)] = [];
  let mut p = skip_ws(cs, p0);
  if at(cs, p) == close {
    p = p + 1;
  } else {
    while true {
      let mut key = "";
      if is_obj {
        let (k, q) = json_string(cs, p)?;
        key = k;
        p = expect_char(cs, q, ":")?;
      }
      let (v, q) = json_value(cs, p)?;
      items = push(items, (key, v));
      p = skip_ws(cs, q);
      if at(cs, p) == "," {
        p = p + 1;
      } else {
        p = expect_char(cs, p, close)?;
        break;
      }
    }
  }
  if !is_obj {
    return Some(("[" ++ join(map(items, |it| it.1), ",") ++ "]", p));
  }
  let keys = map(items, |it| it.0);
  if len(unique(keys)) != len(keys) {
    return None;
  }
  let members = map(sort_by_str(items, |it| it.0), |it| json_encode(it.0) ++ ":" ++ it.1);
  Some(("{" ++ join(members, ",") ++ "}", p))
}
